architecture.h4_f:
msg = CBOR{v:1, текст, одговор_на, испратен_на}
ct = AES-GCM-256-Шифрирај(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {шифриран текст: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, одговор_на?, нишка_ид?, споменува?, испрати_на}
ct = AES-GCM-256-Шифрирај(собен_клуч, нонце, pt, aad=hex(id_room))
жица = CBOR{
  v: 1,
  шифриран текст: hex(ct), // променлива должина
  носе: хексадецимален (12 Б),
  испраќач_псевдо: хексадецимален (16 Б),
  send_at: unix_ms
}

cryptoWire.h5_f:
надворешен = CBOR{
  извор_јазол: hex32,
  target_user: int64,
  внатрешен_шифриран текст: бајти,
  внатрешно_нонце: бајти,
  send_at: unix_ms
}
sig = Ed25519-Sign (извор_приват, надворешен)
POST /federation/deliver { плик: надворешен, знак: хекс64 }

auth.h1_f:
POST /api/автентикација/регистрација
  { корисничко име, лозинка, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Одговор 201 Создаден:
  {token_пристап, refresh_token, user_id, корисничко име, ... }

auth.h3_f:
access_token носивост:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token носивост:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-потпишан со 64-бајтната тајна на јазолот од .env

auth.h4_f:
register_begin(): предизвик = ранд(32)
                    опции = { rp.id, user.id, pubKeyCredParams, предизвик }
                    опции за враќање

register_finish (потврда):
  потврдете ја потврдата против TPM / Безбеден корен на енклава CA
  складирај { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/автентикација/qr/почеток
  → { nonce: 128-битен хексадецимален, ttl: 60 }
QR носивост = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → регистриран нов уред; JWT се вратија.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
шифриран текст = AES-GCM-Шифрирај(собен_клуч, нонс, CBOR_payload, aad=room_id)

Рамка со вентилатор: { type:"m", соба, порака:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {име на датотека, големина, chunk_size_hint}
            ← {upload_id, chunk_size}
парче PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
финализирај POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL на недовршено: 24 ч

files.h4_f:
негира_листа = {
  "апликација/x-dosexec",
  "апликација/x-sharedlib",
  "апликација/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) во deny_list: врати 415

presence.h1_f:
клиент: при првото притискање на тастатурата → испрати {тип:"t", состојба:"почеток"}
         нема повеќе праќање за 3 секунди освен ако состојбата не се промени
         10 секунди по последното притискање на тастатурата → испрати {тип:"t", наведете: "стоп"}
ресивер: автоматско запирање 10 секунди по последниот „старт“ доколку не дојде „стоп“.

calls.h1_f:
POST /api/calls/{room_id}/start {видео, аудио} → call_id
WS емитува {type:"c", kind:"invite", call_id}
WS емитува {тип:"c", вид:"понуда", sdp}
WS емитува {тип:"c", вид:"одговор", sdp}
WS емитува {тип:"c", вид:"кандидат", мраз} × N
POST /api/calls/{call_id}/end

federation.h2_f:
плик = {
  извор_јазол : hex32,
  target_user : int64,
  внатрешен_шифриран текст: бајти,
  inner_nonce: бајти,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(плик))
POST /федерација/испорака { плик, знак }

gossip.h3_f:
реклама = {pubkey, крајна точка, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(реклама))
носивост за озборувања: [..., {ad, sig}, ...]

приемник: потврдете го сиг против ad.pubkey → складирајте ако е во ред
дополнително: PoW од 2^18 водечки нули на {pubkey, endpoint}

stealth.h2_f:
ClientHello бајти = chrome_120_template со {
  случаен = нашиот случаен,
  server_name = нашето име на домаќин (или ECH-завиткано),
  session_id = нашата сесија id,
}
JA4 = t13d_xxxx_xxxx_xxxx (се совпаѓа со тековната стабилна на Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {име: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: домен(t) = base32( SHA256(семе ∥ YYYY-MM-DD) )[:16] + ".пример"

push.h4_f:
iOS NSE: didReceive (барање) { decrypt (request.content.userInfo) }
Android FCM: onMessageReceived (далечинска порака) { decrypt(remoteMessage.data) }
Веб SW: self.addEventListener('push', e => дешифрира(е.податоци))

controller.h2_f:
алатка = знак_алатка
влез = изворно дрво, копчиња/издавање.клуч
манифест = {
  верзија: "0.1.0",
  вграден_ат: unix_ms,
  датотеки: [{ path, sha256, големина}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(манифест))
излез = INTEGRITY.sig.json = {манифест, потпишан_од: pub_hex, знак: sig_hex}

bots.h1_f:
креирај: POST /api/bots {корисничко име, приказ_име, код}
          → {bot_id, знак, pubkey}
работи: во процес (корутин внатрешен јазол)
      OR надворешно (долга анкета /api/bots/{id}/ажурирања, токен-авут'д)
порака: {текст, потпис: Ed25519-Sign(bot_priv, canonical_msg)}

